# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">OKULUMUN BÖLÜMLERİ (أَقْسَامُ الْمَدْرَسَةِ - فِي مَدْرَسَتِي)</text>\n  <rect x="20" y="46" width="210" height="194" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Eril (Müzekker) Mekânlar</text>\n  <text x="125" y="100" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">اَلصَّفُّ (Sınıf / Derslik)</text>\n  <text x="125" y="130" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">اَلْمُخْتَبَرُ (Laboratuvar)</text>\n  <text x="125" y="160" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">اَلْمَقْصَفُ (Kantin)</text>\n  <text x="125" y="190" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">اَلْمَلْعَبُ (Oyun Sahası)</text>\n  <text x="125" y="218" text-anchor="middle" font-size="11" fill="#334155">İşaret ismi olarak هٰذَا kullanılır.</text>\n\n  <rect x="245" y="46" width="210" height="194" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="350" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Dişil (Müennes) Mekânlar</text>\n  <text x="350" y="100" text-anchor="middle" font-size="13" font-weight="bold" fill="#831843">اَلْمَدْرَسَةُ (Okul)</text>\n  <text x="350" y="130" text-anchor="middle" font-size="13" font-weight="bold" fill="#831843">اَلْمَكْتَبَةُ (Kütüphane)</text>\n  <text x="350" y="160" text-anchor="middle" font-size="13" font-weight="bold" fill="#831843">اَلْحَدِيقَةُ (Okul Bahçesi)</text>\n  <text x="350" y="190" text-anchor="middle" font-size="13" font-weight="bold" fill="#831843">غُرْفَةُ الْمُعَلِّمِينَ (Öğretmenler Odası)</text>\n  <text x="350" y="218" text-anchor="middle" font-size="11" fill="#334155">İşaret ismi olarak هٰذِهِ kullanılır.</text>\n\n  <rect x="470" y="46" width="210" height="194" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="575" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Okul Çalışanları ve Öğrenciler</text>\n  <text x="575" y="100" text-anchor="middle" font-size="13" font-weight="bold" fill="#14532d">مُعَلِّمٌ (Erkek Öğretmen)</text>\n  <text x="575" y="128" text-anchor="middle" font-size="13" font-weight="bold" fill="#14532d">مُعَلِّمَةٌ (Kadın Öğretmen)</text>\n  <text x="575" y="156" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">طَالِبٌ / طَالِبَةٌ (Öğrenci)</text>\n  <text x="575" y="184" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">صَدِيقِي / صَدِيقَتِي (Arkadaşım)</text>\n  <text x="575" y="216" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">«اَلْعِلْمُ نَافِعٌ» (İlim faydalıdır.)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HARF-İ CERLER (فِي / إِلَى) VE «أَيْنَ...؟» SORU KALIBI</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">فِي (-de / -da / içinde) Kullanımı</text>\n  <text x="180" y="102" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">أَيْنَ الطَّالِبُ؟ (Öğrenci nerededir?)</text>\n  <text x="180" y="130" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f172a">• اَلطَّالِبُ فِي الصَّفِّ. (Öğrenci sınıftadır.)</text>\n  <text x="180" y="156" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f172a">• اَلْمُعَلِّمُ فِي الْمُخْتَبَرِ. (Öğretmen laboratuvardadır.)</text>\n  <text x="180" y="182" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f172a">• صَدِيقَتِي فِي الْمَكْتَبَةِ. (Arkadaşım kütüphanededir.)</text>\n  <text x="180" y="216" text-anchor="middle" font-size="11" fill="#334155">فِي harf-i cerrinden sonraki ismin sonu kesralı (-i) okunur.</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">إِلَى (-e / -a / yönelme) Kullanımı</text>\n  <text x="520" y="102" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">إِلَى أَيْنَ تَذْهَبُ؟ (Nereye gidiyorsun?)</text>\n  <text x="520" y="130" text-anchor="middle" font-size="12" font-weight="bold" fill="#78350f">• أَذْهَبُ إِلَى الْمَدْرَسَةِ. (Okula gidiyorum.)</text>\n  <text x="520" y="156" text-anchor="middle" font-size="12" font-weight="bold" fill="#78350f">• أَذْهَبُ إِلَى الْمَقْصَفِ. (Kantine gidiyorum.)</text>\n  <text x="520" y="182" text-anchor="middle" font-size="12" font-weight="bold" fill="#78350f">• أَذْهَبُ إِلَى الْحَدِيقَةِ. (Bahçeye gidiyorum.)</text>\n  <text x="520" y="216" text-anchor="middle" font-size="11" fill="#475569">إِلَى harf-i cerrinden sonraki ismin sonu da kesralı (-i) olur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">OKUL İÇİ İLETİŞİM, YÖNERGELER VE SESLETİM KURALLARI</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Diyalog ve Sınıf Yönergeleri</text>\n  <text x="182" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• هَلْ أَنْتَ فِي الْمَكْتَبَةِ؟ (Kütüphanede misin?)</text>\n  <text x="182" y="128" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• نَعَمْ، أَنَا فِي الْمَكْتَبَةِ. (Evet, kütüphanedeyim.)</text>\n  <text x="182" y="156" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">• اِفْتَحْ دَفْتَرَكَ / أَغْلِقِ الْبَابَ (Defterini aç / Kapıyı kapat)</text>\n  <text x="182" y="184" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">• أَعْطِنِي الْقَلَمَ مِنْ فَضْلِكَ (Lütfen bana kalemi ver)</text>\n  <text x="182" y="214" text-anchor="middle" font-size="11" fill="#334155">مِنْ فَضْلِكَ (erkek) / مِنْ فَضْلِكِ (kız): Lütfen</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Şemsî - Kamerî Lam ve Okuma</text>\n  <text x="517" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Şemsî (ال okunmaz, harf şeddelenir): اَلصَّفُّ - اَلطَّالِبُ</text>\n  <text x="517" y="130" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Kamerî (ال cezimli okunur): اَلْمَدْرَسَةُ - اَلْمَكْتَبَةُ</text>\n  <text x="517" y="158" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Cezimli Heceler: مَقْصَفٌ - مُخْتَبَرٌ - دَفْتَرٌ</text>\n  <text x="517" y="186" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Uzatma (Med) Sesleri: حَدِيقَةٌ - طَالِبَةٌ - سَبُّورَةٌ</text>\n  <text x="517" y="214" text-anchor="middle" font-size="11" fill="#475569">Harflerin başta, ortada ve sonda birleşme şekilleri</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
